<?php
header('Content-Type: application/json; charset=utf-8');
require_once __DIR__.'/../Config/mikrotik.php'; require_once __DIR__.'/../library/routeros_api.class.php';
try{$cfg=new MikroTikConfig();$id=(int)($_GET['router_id']??0);if($id){require_once __DIR__.'/../Config/database.php';$pdo=(new Database())->connect();$s=$pdo->prepare('SELECT * FROM router WHERE id=? LIMIT 1');$s->execute([$id]);$router=$s->fetch(PDO::FETCH_ASSOC);}else{$router=$cfg->getRouter();}if(!$router){echo json_encode(['status'=>'offline','message'=>'Router tidak tersedia']);exit;}$api=new RouterosAPI();$api->debug=false;if(!$api->connect($router['ip_address'],$router['username'],$router['password'],$router['api_port'])){echo json_encode(['status'=>'offline','message'=>'Router tidak dapat terhubung']);exit;}$items=$api->comm('/ip/address/print');$api->disconnect();$rows=[];foreach($items as $x){$rows[]=['id'=>$x['.id']??'','address'=>$x['address']??'-','network'=>$x['network']??'-','interface'=>$x['interface']??'-','actual_interface'=>$x['actual-interface']??($x['interface']??'-'),'disabled'=>isset($x['disabled']),'dynamic'=>isset($x['dynamic']),'invalid'=>isset($x['invalid'])];}echo json_encode(['status'=>'online','router'=>$router['router_name'],'router_id'=>(int)$router['id'],'addresses'=>$rows]);}catch(Throwable $e){http_response_code(500);echo json_encode(['status'=>'error','message'=>$e->getMessage()]);}